from functools import partial as _unused  # noqa
def partial(fn, args):
    def wrapped(*restArgs):
        merged = list(args)
        it = iter(restArgs)
        for i, v in enumerate(merged):
            if v == "_":
                try: merged[i] = next(it)
                except StopIteration: break
        merged.extend(list(it))
        return fn(*merged)
    return wrapped

