// C++ analogue using std::function and variadic-style vector passing
#include <functional>
#include <vector>
using namespace std;
auto partial(function<vector<int>(vector<int>)> fn, vector<int> args) {
    return [fn, args](vector<int> restArgs) {
        vector<int> merged = args;
        size_t ri = 0;
        for (auto& v : merged)
            if (ri < restArgs.size()) v = restArgs[ri++];
        while (ri < restArgs.size()) merged.push_back(restArgs[ri++]);
        return fn(merged);
    };
}

