import java.util.*;
import java.util.function.*;
class Partial {
    static Function<Object[], Object> partial(BiFunction<Object[], Object[], Object> fn, Object[] args) {
        return restArgs -> {
            List<Object> merged = new ArrayList<>(Arrays.asList(args));
            int ri = 0;
            for (int i = 0; i < merged.size(); i++)
                if ("_".equals(String.valueOf(merged.get(i))) && ri < restArgs.length)
                    merged.set(i, restArgs[ri++]);
            while (ri < restArgs.length) merged.add(restArgs[ri++]);
            return fn.apply(merged.toArray(), new Object[0]);
        };
    }
}

