var partial = function(fn, args) {
    return function(...restArgs) {
        const merged = [...args];
        let ri = 0;
        for (let i = 0; i < merged.length && ri < restArgs.length; i++)
            if (merged[i] === "_") merged[i] = restArgs[ri++];
        while (ri < restArgs.length) merged.push(restArgs[ri++]);
        return fn(...merged);
    };
};
